import sys

class N:
    __slots__ = ('v', 'nxt')
    def __init__(self, v=0, nxt=None):
        self.v = v; self.nxt = nxt

def build_cycle(vals, pos):
    if not vals: return None
    head = N(vals[0])
    nodes = [head]
    for v in vals[1:]:
        nodes[-1].nxt = N(v)
        nodes.append(nodes[-1].nxt)
    if pos >= 0:
        nodes[-1].nxt = nodes[pos]
    return head

def has_cycle_brute(head):
    seen = set()
    cur = head
    while cur is not None:
        if id(cur) in seen: return True
        seen.add(id(cur))
        cur = cur.nxt
    return False

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    if n == 0:
        vals = []
        pos = int(data[1])
    else:
        vals = list(map(int, data[1:1 + n]))
        pos = int(data[1 + n])
    head = build_cycle(vals, pos)
    print('true' if has_cycle_brute(head) else 'false')

